    static func parse(_ blob: String) -> [String: String] {
        var lookup: [String: String] = [:]
        lookup.reserveCapacity(20000)
        for line in blob.split(separator: "\n", omittingEmptySubsequences: true) {
            guard let tab = line.firstIndex(of: "\t") else { continue }
            lookup[String(line[..<tab])] = String(line[line.index(after: tab)...])
        }
        return lookup
    }
}
